"""Undo, redo and history (docs/undo.md).

The stacks are worked out from the journal alone (section 2). Each step works
on a copy of the store and of the stacks; nothing is written here.
"""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.context import Context
from binkeep.errors import DataError, Refused
from binkeep.store import Store


class Stacks:
    """The *done* and *undone* stacks, and the operations that were dropped.

    *done* holds operation entries; *undone* holds (operation entry, undo line).
    """

    def __init__(self):
        self.done: list[dict] = []
        self.undone: list[tuple[dict, dict]] = []
        self.dropped: list[dict] = []

    def push_operation(self, e: dict) -> None:
        self.done.append(e)
        self.dropped.extend(op for op, _ in self.undone)
        self.undone.clear()

    def apply_undo(self, e: dict) -> None:
        if not self.done or not _names(e, self.done[-1]):
            raise DataError("journal", f"undo #{e['seq']} does not match the top of done")
        self.undone.append((self.done.pop(), e))

    def apply_redo(self, e: dict) -> None:
        if not self.undone or not _names(e, self.undone[-1][0]):
            raise DataError("journal", f"redo #{e['seq']} does not match the top of undone")
        self.done.append(self.undone.pop()[0])

    def copy(self) -> "Stacks":
        s = Stacks()
        s.done, s.undone, s.dropped = list(self.done), list(self.undone), list(self.dropped)
        return s


def _names(line: dict, op: dict) -> bool:
    target = line.get("target")
    return type(target) is int and target == op["seq"]


def replay(entries: list[dict]) -> Stacks:
    s = Stacks()
    for e in entries:
        if e["op"] in journal.OPS:
            s.push_operation(e)
        elif e["op"] == "undo":
            s.apply_undo(e)
        elif e["op"] == "redo":
            s.apply_redo(e)
    return s


def _bad(e: dict, what: str) -> DataError:
    return DataError("journal", f"#{e.get('seq')}: {what}")


def _code(e: dict, value) -> str:
    if not isinstance(value, str):
        raise _bad(e, "bad bin code")
    return normalize(value)


def _int(e: dict, value) -> int:
    if type(value) is not int:
        raise _bad(e, "bad quantity")
    return value


def _format1_changes(ctx: Context, e: dict) -> list[tuple[str, int]]:
    """The (bin, change) pairs that taking the line back makes, in that order."""
    try:
        op = e["op"]
        if op == "receive":
            qty = _int(e, e["qty"])
            if e.get("uom") == "pk":
                item = ctx.items.get(e["sku"])
                if item is None:
                    raise Refused("unknown-sku", f"no item {e['sku']}")
                qty *= item.pack_size
            return [(_code(e, e["bin"]), -qty)]
        if op == "issue":
            changes = []
            for pick in reversed(e["picks"]):
                code, qty = pick
                changes.append((_code(e, code), _int(e, qty)))
            return changes
        if op == "move":
            qty = _int(e, e["qty"])
            return [(_code(e, e["to"]), -qty), (_code(e, e["from"]), qty)]
    except (KeyError, TypeError, ValueError):
        raise _bad(e, "malformed format 1 line") from None
    raise _bad(e, f"cannot take back {e['op']}")


def _set_effects(ctx: Context, e: dict, effects) -> list[tuple[str, int]]:
    """(bin, quantity to set) for the recorded effects, last first."""
    if not isinstance(effects, list):
        raise _bad(e, "no effects")
    out = []
    for f in reversed(effects):
        if not isinstance(f, dict) or not isinstance(f.get("bin"), str):
            raise _bad(e, "bad effect")
        out.append((normalize(f["bin"]), _int(e, f.get("before"))))
    return out


def _carry_out(ctx: Context, store: Store, seq: int, kind: str, op: dict, targets, absolute: bool) -> dict:
    """Sets the bins; targets are (bin, quantity) or, when not absolute, (bin, change)."""
    for code, _ in targets:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
    sku, effects = op["sku"], []
    for code, value in targets:
        before = store.qty(sku, code)
        after = value if absolute else before + value
        store.restore(sku, code, after)
        effects.append({"bin": code, "before": before, "after": after})
    return journal.entry(seq, kind, ctx.by, sku, target=op["seq"], effects=effects)


def _step(ctx: Context, store: Store, stacks: Stacks, kind: str, seq: int) -> dict:
    if kind == "undo":
        if not stacks.done:
            raise Refused("nothing-to-undo", "nothing to undo")
        op = stacks.done[-1]
        if op["op"] == "fix":
            raise Refused("barrier", f"#{op['seq']} is a fix")
        if op.get("v") == 2:
            targets, absolute = _set_effects(ctx, op, op.get("effects")), True
        elif op["op"] == "count":
            raise Refused("irreversible", f"#{op['seq']} is a count without a recorded quantity")
        else:
            targets, absolute = _format1_changes(ctx, op), False
        line = _carry_out(ctx, store, seq, "undo", op, targets, absolute)
        stacks.apply_undo(line)
        return line
    if not stacks.undone:
        raise Refused("nothing-to-redo", "nothing to redo")
    op, undo_line = stacks.undone[-1]
    targets = _set_effects(ctx, undo_line, undo_line.get("effects"))
    line = _carry_out(ctx, store, seq, "redo", op, targets, True)
    stacks.apply_redo(line)
    return line


def run(ctx: Context, kind: str, steps: int):
    """Returns the new store and the lines to append, or raises on the first refused step."""
    stacks, store = replay(ctx.entries), ctx.store.copy()
    seq, lines = journal.next_seq(ctx.entries), []
    for _ in range(steps):
        line = _step(ctx, store, stacks, kind, seq)
        lines.append(line)
        seq += 1
    return store, lines


