def history(ctx: Context, limit: int) -> list[tuple[dict, str]]:
    """The latest operations, newest first, with their status."""
    s = replay(ctx.entries)
    state = {}
    for e in s.dropped:
        state[id(e)] = "dropped"
    for e, _ in s.undone:
        state[id(e)] = "undone"
    for e in s.done:
        state[id(e)] = "barrier" if e["op"] == "fix" else "done"
    ops = [e for e in ctx.entries if e["op"] in journal.OPS]
    return [(e, state[id(e)]) for e in reversed(ops[-limit:])]

