def step_lines(entry: dict, op: dict) -> list[str]:
    """An undo or redo line, with the operation it undoes or redoes in the heading."""
    head = f"#{entry['seq']} {entry['op']} {entry['sku']} (#{entry['target']} {op['op']})"
    return [head] + [f"  {e['bin']} {e['before']} -> {e['after']}" for e in entry["effects"]]


