def _step(ctx: Context, kind: str, steps: int) -> list[str]:
    store, steps_done = undo.run(ctx, kind, steps)
    ctx.commit(store, [line for line, _ in steps_done])
    return [text for line, op in steps_done for text in step_lines(line, op)]


def cmd_undo(ctx, a):
    return _step(ctx, "undo", a.steps)


def cmd_redo(ctx, a):
    return _step(ctx, "redo", a.steps)


